S="C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/5cebfb2a-057d-4fc7-8a6b-5129a86210ee/scratchpad/wol"; cat > "$S/tools2/dump_all.py" <<'EOF'
"""dump_all.py <out.jsonl>: every prefab in core, all components (typetree), pptr resolved to names. One JSON per line."""
import UnityPy, json, sys, os
SA="C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/StreamingAssets/core"
env=UnityPy.load(SA)
objs={o.path_id:o for o in env.objects}
cont={o.path_id:p for p,o in env.container.items()}
namecache={}
def pname(pid):
    if pid in namecache: return namecache[pid]
    o=objs.get(pid); r=None
    if o is None: r="?ext"
    elif pid in cont: r=cont[pid]
    else:
        try:
            tt=o.type.name
            if tt=="GameObject": r="GO:"+o.read_typetree()["m_Name"]
            elif tt in ("AnimatorController","AnimationClip","Sprite","Material","PhysicsMaterial2D","Texture2D","TextAsset"): r=tt+":"+o.read_typetree().get("m_Name","")
            elif tt=="MonoBehaviour":
                t=o.read_typetree(); go=objs.get(t["m_GameObject"]["m_PathID"])
                r="MB:"+(go.read_typetree()["m_Name"] if go else "?")
            else: r=tt
        except Exception as e: r="err"
    namecache[pid]=r; return r
SKIPT={"SpriteRenderer","ParticleSystem","ParticleSystemRenderer","CanvasRenderer","Light","LineRenderer","TrailRenderer","Canvas","FlareLayer","GUILayer","AudioListener","AudioHighPassFilter"}
SKIPK={"m_GameObject","m_Enabled","m_Script","m_ObjectHideFlags","m_CorrespondingSourceObject","m_PrefabInstance","m_PrefabAsset","m_EditorHideFlags","m_EditorClassIdentifier","m_Name"}
def clean(v):
    if isinstance(v,dict):
        if set(v)=={"m_FileID","m_PathID"}: 
            return None if v["m_PathID"]==0 else {"ref":pname(v["m_PathID"])}
        if "_baseValue" in v and "_currentValue" in v: return v["_baseValue"]
        d={}
        for k,x in v.items():
            if k in SKIPK: continue
            c=clean(x)
            if c is not None and c!={} and c!=[]: d[k]=c
        return d
    if isinstance(v,list):
        l=[clean(x) for x in v]; return [x for x in l if x is not None and x!={}]
    return v
def walk(goobj,prefix,out,parent_scale):
    t=goobj.read_typetree(); gname=t["m_Name"]; comps=[]
    scale=list(parent_scale); pos=None; lscale=None; children=[]
    for c in t["m_Component"]:
        pid=c["component"]["m_PathID"]; o=objs.get(pid)
        if o is None: continue
        tn=o.type.name
        if tn in("Transform","RectTransform"):
            tt=o.read_typetree(); ls=tt["m_LocalScale"]; lscale=[ls["x"],ls["y"],ls["z"]]
            scale=[parent_scale[i]*lscale[i] for i in range(3)]
            p=tt["m_LocalPosition"]; pos=[p["x"],p["y"],p["z"]]
            children=[ch["m_PathID"] for ch in tt["m_Children"]]
            continue
        if tn in SKIPT: continue
        try:
            tt=o.read_typetree()
            if tn=="MonoBehaviour":
                cls=objs[tt["m_Script"]["m_PathID"]].read_typetree()["m_ClassName"] if tt["m_Script"]["m_PathID"] in objs else "?"
            else: cls=tn
            en=tt.get("m_Enabled",1)
            comps.append({"class":cls,"enabled":en,"fields":clean(tt)})
        except Exception as e:
            comps.append({"class":tn,"error":str(e)})
    out.append({"go":prefix+gname,"active":t.get("m_IsActive",1),"layer":t.get("m_Layer"),"tag":t.get("m_Tag"),"localPos":pos,"localScale":lscale,"worldScale":scale,"components":comps})
    for cp in children:
        try:
            ch=objs[cp].read(); cg=ch.m_GameObject.read()
            walk(cg,prefix+gname+"/",out,scale)
        except Exception as e: out.append({"go":prefix+gname+"/?","error":str(e)})
n=0
with open(sys.argv[1],"w",encoding="utf-8") as f:
    for p,o in sorted(env.container.items()):
        if not p.endswith(".prefab"): continue
        try:
            out=[]; walk(o.read(),"",out,[1,1,1])
            f.write(json.dumps({"path":p,"objects":out},ensure_ascii=False)+"\n"); n+=1
        except Exception as e: print("FAIL",p,e)
print("prefabs",n)
EOF
time "$S/venv/Scripts/python.exe" -I "$S/tools2/dump_all.py" "$S/data/allprefabs.jsonl" 2>&1 | tail; ls -la "$S/data/allprefabs.jsonl"

