S="C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/5cebfb2a-057d-4fc7-8a6b-5129a86210ee/scratchpad/wol"; PY="$S/venv/Scripts/python.exe"; cat > "$S/tools2/q.py" <<'EOF'
import json,sys,re
D="C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/5cebfb2a-057d-4fc7-8a6b-5129a86210ee/scratchpad/wol/data/allprefabs.jsonl"
def load():
    return [json.loads(l) for l in open(D,encoding="utf-8")]
EOF
cat > "$S/tools2/cls.py" <<'EOF'
import sys; sys.path.insert(0,sys.argv[0].rsplit("/",1)[0]) if False else None
exec(open(sys.argv[0].replace("cls.py","q.py")).read())
import collections
P=load()
pat=re.compile(sys.argv[1],re.I)
res=collections.defaultdict(set)
for p in P:
    for o in p["objects"]:
        for c in o.get("components",[]):
            if pat.search(c["class"]): res[c["class"]].add(p["path"])
for k,v in sorted(res.items()): print(k,len(v),sorted(v)[:4])
EOF
