import UnityPy, collections, re, json
DD="C:/Program Files (x86)/Steam/steamapps/common/Wizard of Legend/WizardOfLegend_Data/"
pat=re.compile(r"^(ItemStoreItem|SkillStoreItem|HealStoreItem|OutfitDestructible|OutfitStoreItem|WardrobeNpc|CursedMerchant|ItemMerchant|SkillMerchant|OutfitMerchant|Merchant|BankerNpc)",re.I)
res={}
for lv in (5,14,15):
    env=UnityPy.load(DD+"level%d"%lv)
    objs={o.path_id:o for o in env.objects}
    tt={}
    def gt(pid):
        if pid not in tt: tt[pid]=objs[pid].read_typetree()
        return tt[pid]
    def path(pid):
        t=gt(pid); names=[t["m_Name"]]; tr=None
        for c in t["m_Component"]:
            x=objs.get(c["component"]["m_PathID"])
            if x and x.type.name in("Transform","RectTransform"): tr=x.read_typetree()
        while tr and tr["m_Father"]["m_PathID"]:
            f=objs[tr["m_Father"]["m_PathID"]].read_typetree(); names.append(gt(f["m_GameObject"]["m_PathID"])["m_Name"]); tr=f
        return "/".join(reversed(names))
    cnt=collections.Counter()
    for o in env.objects:
        if o.type.name=="GameObject":
            n=gt(o.path_id)["m_Name"]
            if pat.match(n):
                p=path(o.path_id); parent=p.rsplit("/",1)[0] if "/" in p else ""
                cnt[(re.sub(r" \(\d+\)$","",n),parent)]+=1
    res[lv]={"%s @ %s"%k:v for k,v in sorted(cnt.items())}
    print(lv); [print("  ",k,v) for k,v in sorted(cnt.items())]
json.dump(res,open(S+"/data/scene_store_counts.json","w"),indent=1)
EOF
"$PY" -I "$S/tools2/scenes4.py" 2>&1 | cut -c1-250

