LAYERS={0:'Default',1:'TransparentFX',2:'Ignore Raycast',4:'Water',5:'UI',8:'Player',9:'Enemy',10:'Environment',11:'Wall',12:'Pit',13:'LowerWall',14:'Obstacle',15:'PlayerDetector',16:'Beam',17:'Minimap',18:'ItemFloorContact',19:'AllyFloorContact',20:'IgnoreEnemyAllyFloorContact',21:'PreventFall',22:'PreventFallPitCollider',23:'Destructible',24:'EnemyFloorContact',25:'WallAndObstacle',26:'WallOnly',27:'IgnoreEnemyFloorContact',28:'IgnoreAllyEnemyFloorContact',29:'Attack',30:'WallDetector'}
BODY={0:"Dynamic",1:"Kinematic",2:"Static"}
P=load()
byp={p["path"]:p for p in P}
def isroom(p): return "/data/rooms/" in p
def kind(p):
    m=re.match(r"assets/prefabs/([^/]+)",p)
    return m.group(1) if m else ("room" if isroom(p) else "other")
# ---------- physics: rigidbodies + colliders
rb_rows=[]; col_rows=[]
for p in P:
    if isroom(p["path"]): continue
    for o in p["objects"]:
        for c in o.get("components",[]):
            f=c.get("fields",{}); cl=c["class"]
            ws=o.get("worldScale") or [1,1,1]
            lay=LAYERS.get(o.get("layer"),o.get("layer"))
            if cl=="Rigidbody2D":
                rb_rows.append([p["path"],kind(p["path"]),o["go"],lay,BODY.get(f.get("m_BodyType")),f.get("m_Mass"),f.get("m_LinearDrag"),f.get("m_AngularDrag"),f.get("m_GravityScale"),f.get("m_Constraints"),f.get("m_CollisionDetection"),f.get("m_Interpolate"),f.get("m_SleepingMode")])
            if cl in("BoxCollider2D","CircleCollider2D","CapsuleCollider2D"):
                off=f.get("m_Offset",{"x":0,"y":0}); ax,ay=abs(ws[0]),abs(ws[1])
                if cl=="CircleCollider2D":
                    r=f.get("m_Radius",0); sx=sy=""; wx=wy=2*r*max(ax,ay)
                else:
                    sz=f.get("m_Size",{}); sx,sy=sz.get("x",0),sz.get("y",0); r=""; wx,wy=sx*ax,sy*ay
                mat=(f.get("m_Material") or {}).get("ref","")
                col_rows.append([p["path"],kind(p["path"]),o["go"],lay,cl,f.get("m_IsTrigger",False),sx,sy,r,off.get("x",0),off.get("y",0),round(ax,4),round(ay,4),round(wx,4),round(wy,4),mat])
def wcsv(name,hdr,rows):
    with open(os.path.join(OUT,name),"w",newline="",encoding="utf-8") as fh:
        w=csv.writer(fh); w.writerow(hdr)
        for r in rows: w.writerow([round(x,5) if isinstance(x,float) else x for x in r])
wcsv("physics_bodies.csv",["prefab","category","gameobject","layer","body_type","mass","linear_drag","angular_drag","gravity_scale","constraints","collision_detection","interpolate","sleeping_mode"],rb_rows)
wcsv("colliders.csv",["prefab","category","gameobject","layer","type","is_trigger","size_x","size_y","radius","offset_x","offset_y","world_scale_x","world_scale_y","world_size_x","world_size_y","physics_material"],col_rows)
print("rigidbodies",len(rb_rows),"colliders",len(col_rows))
# ---------- helpers for topic JSON
NOISE={"m_SpriteTilingProperty","m_Density","m_UsedByEffector","m_UsedByComposite","m_AutoTiling","lastAttack","myOrigin","originalRotation","originalScale","currentSurroundPoint","moveVector","dashVector","orbitVector"}
def flat(v,pre=""):
    if isinstance(v,dict):
        for k,x in v.items():
            if k in NOISE: continue
            yield from flat(x,pre+("." if pre else "")+k)
    elif isinstance(v,list):
        for i,x in enumerate(v): yield from flat(x,pre+"[%d]"%i)
    elif isinstance(v,(bool,int,float,str)): yield pre,v
def entries(path,classes_re=None,skip_classes=(),only_num=False,go_re=None):
    out=[]
    for o in byp[path]["objects"]:
        if go_re and not re.search(go_re,o["go"]): continue
        for c in o.get("components",[]):
            if "fields" not in c: continue
            if classes_re and not re.search(classes_re,c["class"]): continue
            if c["class"] in skip_classes: continue
            for k,v in flat(c["fields"]):
                if only_num and not isinstance(v,(int,float)): continue
                if isinstance(v,str) and v=="": continue
                out.append({"prefab":path,"gameobject":o["go"],"component":c["class"],"field":k,"value":v})
    return out
