def code_consts(files):
    out=[]
    rx=re.compile(r"^\s*(?:(?:public|private|protected|internal|static|readonly|const)\s+)+(?:float|int|double|Vector2|Vector3)\s+(\w+)\s*=\s*([^;]+);")
    for f in files:
        for i,l in enumerate(open(os.path.join(SRC,f),encoding="utf-8",errors="replace"),1):
